 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = set()
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w
                            and p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            objects.append([color, cells])

    # Let every connected object slide right until the wall or another object stops it.
    moved = True
    while moved:
        moved = False
        occupied = set().union(*(obj[1] for obj in objects)) if objects else set()
        for color, cells in sorted(objects, key=lambda obj: max(c for _, c in obj[1]), reverse=True):
            if all(c + 1 < w and (r, c + 1) not in occupied
                   for r, c in cells):
                occupied.difference_update(cells)
                shifted = {(r, c + 1) for r, c in cells}
                cells.clear()
                cells.update(shifted)
                occupied.update(cells)
                moved = True

    out = [[0] * w for _ in range(h)]
    for color, cells in objects:
        for r, c in cells:
            out[r][c] = color
    return out
